FUNCTION_BLOCK FB_LRF_ArgonStirringSlagBalance
(*
 * ===================================================================================================
 * LUMINA AUTOMATION CYBER-PHYSICAL SYSTEMS KERNEL: HEAVY METALLURGY DIVISION
 * ARCHITECTURE: IEC 61131-3 HIGH-INTEGRITY CONTROL FOR LADLE REFINING FURNACE (LRF)
 * SUBSYSTEM: DUAL POROUS PLUG ARGON STIRRING, THERMODYNAMIC DESULFURIZATION & SLAG EQUILIBRIUM
 *
 * METALLURGICAL THEORY & CONTROL ARCHITECTURE IMPLEMENTED:
 * 1. 2oo3 Triple Modular Redundancy (TMR) Sensor Median Voting & Deviation Diagnostics:
 *    - Liquid steel immersion pyrometer / continuous optical fiber (T1, T2, T3) [deg C]
 *    - Bottom Porous Plug A and Plug B line pressure transducers (P1, P2, P3) [bar]
 *    - Autonomous channel fault detection, discrepancy filtering, and degraded 1oo2 failover
 * 2. Mori & Nomura Stirring Energy Dissipation Rate (epsilon [W/ton]):
 *    epsilon = (14.23 * Q_Ar / M_steel) * T_bath * ln(1 + 0.00968 * rho_steel * H_bath / P_atm)
 * 3. Asai / Szekely Plume Eye Area Model & Re-oxidation Limiting Constraint:
 *    D_eye = C_eye * sqrt(Q_Ar^2 / (g * H_bath)) * (1.0 - h_slag / H_crit)
 * 4. Slag Optical Basicity (Lambda) & Sulfide Capacity (C_S) Equilibrium Formulation:
 *    log10(C_S) = -13913.0 / T_bath + 42.42 * Lambda - 11.75
 *    Partition ratio: L_S = (wt% S)_slag / [wt% S]_steel = C_S / (f_S * a_O)
 * 5. Discrete-Time State-Space Formulation & Model Predictive Control (MPC):
 *    x[k+1] = A_sys * x[k] + B_sys * u[k] + E_dist * d[k]
 *    State Vector: x = [[S] (sulfur ppm), d[S]/dt, T_bath (deg C)]^T
 *    Control Input: u = [Q_Ar_demand (Nm3/h)]
 *    Analytical quadratic cost optimization with stirring eye and thermal constraints
 * 6. Porous Plug Impedance Diagnostics (Z = P / Q) & Graceful Degradation:
 *    - Clogging detection (Z > Z_clog) -> High-pressure argon pulse burn-through command
 *    - Refractory erosion / steel breakout risk (Z < Z_erosion) -> Isolate Plug A, switch to Plug B
 *    - Dual plug failure -> Emergency deployment of auxiliary top lance argon injection
 * ===================================================================================================
 *)

VAR_INPUT
    bEnable                 : BOOL;     (* Master function block execution permit from LRF supervisory PLC *)
    bEmergencyStop          : BOOL;     (* Hardwired SIL-3 Safety interlock / Emergency Stop OK signal *)
    bAutoMode               : BOOL;     (* Mode select: TRUE = MPC Closed-Loop, FALSE = Manual Flow Tracking *)
    bAcknowledgeFaults      : BOOL;     (* Operator pushbutton to clear latched warning and trip alarms *)

    (* Primary Gas Supply and Process Hydraulic Inputs *)
    rArgonSupplyPress_bar   : REAL;     (* Main high-pressure Argon manifold header pressure [bar] *)
    rPlugA_PresSens1_bar    : REAL;     (* Porous Plug A delivery line pressure sensor 1 (TMR 2oo3) [bar] *)
    rPlugA_PresSens2_bar    : REAL;     (* Porous Plug A delivery line pressure sensor 2 (TMR 2oo3) [bar] *)
    rPlugA_PresSens3_bar    : REAL;     (* Porous Plug A delivery line pressure sensor 3 (TMR 2oo3) [bar] *)
    rPlugB_PresSens1_bar    : REAL;     (* Porous Plug B delivery line pressure sensor 1 (TMR 2oo3) [bar] *)
    rPlugB_PresSens2_bar    : REAL;     (* Porous Plug B delivery line pressure sensor 2 (TMR 2oo3) [bar] *)
    rPlugB_PresSens3_bar    : REAL;     (* Porous Plug B delivery line pressure sensor 3 (TMR 2oo3) [bar] *)
    rArgonFlowActual_Nm3h   : REAL;     (* Thermal mass flow meter measured total argon gas flow [Nm3/h] *)

    (* Thermal, Electrical, and Metallurgical Measurement Inputs *)
    rBathTempSens1_degC     : REAL;     (* Liquid steel bath temperature sensor channel 1 (TMR 2oo3) [deg C] *)
    rBathTempSens2_degC     : REAL;     (* Liquid steel bath temperature sensor channel 2 (TMR 2oo3) [deg C] *)
    rBathTempSens3_degC     : REAL;     (* Liquid steel bath temperature sensor channel 3 (TMR 2oo3) [deg C] *)
    rArcCurrentTotal_kA     : REAL;     (* Total 3-phase graphite electrode heating current [kA] *)
    rDissolvedOxygen_ppm    : REAL;     (* Celox sub-lance electrochemical dissolved oxygen activity a_O [ppm] *)
    rInitialSulfur_ppm      : REAL;     (* Spark optical emission spectrometer initial sulfur concentration [ppm] *)
    rTargetSulfur_ppm       : REAL;     (* Target final grade specification maximum sulfur concentration [ppm] *)

    (* Ladle Geometry and Slag Conditioning Inputs *)
    rSteelMass_ton          : REAL;     (* Net liquid steel bath mass in ladle car [ton] *)
    rSlagMass_ton           : REAL;     (* Synthetic top cover slag mass [ton] *)
    rSlagBasicity_B2        : REAL;     (* Slag binary basicity ratio (wt% CaO / wt% SiO2) [-] *)
    rSlagFeO_MnO_pct        : REAL;     (* Total reducible oxidizing oxides in slag (FeO + MnO) [wt%] *)
    rSlagAl2O3_pct          : REAL;     (* Slag alumina content for fluidity and viscosity calculation [wt%] *)

    (* Auxiliary Subsystem Interlocks *)
    bTopLanceArgonReady     : BOOL;     (* Auxiliary emergency top bubbling lance ready on hoist carriage *)
    tScanCycleTime          : TIME;     (* Deterministic PLC cyclic task execution sample period, e.g., T#100MS *)
END_VAR

VAR_OUTPUT
    (* Status and Diagnostic Words *)
    bSystemReady            : BOOL;     (* Controller online, verified healthy, and operational *)
    bSequenceActive         : BOOL;     (* LRF refining cycle and automated stirring sequence running *)
    wStatusWord             : WORD;     (* Status bitmask: 0=Idle, 1=Purge, 2=Heat, 3=SlagBal, 4=DeepDesulf, 5=Rinse, 6=Degraded *)
    wAlarmWord1             : WORD;     (* Critical shutdown trip alarms: Bit0=P_SupplyLow, Bit1=Breakthrough, Bit2=TMR_Fail, Bit3=OverTemp *)
    wAlarmWord2             : WORD;     (* Advisory alarms: Bit0=CloggedPlugA, Bit1=CloggedPlugB, Bit2=SlagOxidizing, Bit3=EyeExcessive *)

    (* Actuator Demands and Control Signals *)
    rArgonFlowSetpoint_Nm3h : REAL;     (* Closed-loop demand output to argon Mass Flow Controller (MFC) [Nm3/h] *)
    rPlugA_ControlValve_pct : REAL;     (* Analog modulation command to Porous Plug A flow control valve [0..100%] *)
    rPlugB_ControlValve_pct : REAL;     (* Analog modulation command to Porous Plug B flow control valve [0..100%] *)
    bEmergencyLanceDeploy   : BOOL;     (* Digital command to lower and ignite emergency top argon lance *)
    bPulseBurnoutCmd_A      : BOOL;     (* High-pressure gas shock pulse blast command to clear Plug A clogging *)
    bPulseBurnoutCmd_B      : BOOL;     (* High-pressure gas shock pulse blast command to clear Plug B clogging *)

    (* Online Kinetic State Estimations & Observability *)
    rEstimatedSulfur_ppm    : REAL;     (* Real-time state-space observer predicted dissolved sulfur [ppm] *)
    rDesulfRate_ppm_per_min : REAL;     (* Instantaneous desulfurization kinetic rate [ppm/min] *)
    rStirringPower_W_ton    : REAL;     (* Specific stirring power dissipation rate epsilon [W/ton] *)
    rEyeDiameter_m          : REAL;     (* Calculated open plume eye diameter in ladle slag cover [m] *)
    rEquilibriumSulfur_ppm  : REAL;     (* Theoretical thermodynamic equilibrium sulfur limit [S]_eq [ppm] *)
    rVotedBathTemp_degC     : REAL;     (* 2oo3 TMR median voted liquid steel bath temperature [deg C] *)
    rVotedPlugA_Pres_bar    : REAL;     (* 2oo3 TMR median voted back-pressure on Porous Plug A [bar] *)
    rVotedPlugB_Pres_bar    : REAL;     (* 2oo3 TMR median voted back-pressure on Porous Plug B [bar] *)
    bDesulfTargetReached    : BOOL;     (* Flag indicating target sulfur endpoint is reached within metallurgical tolerance *)
    iOperatingState         : INT;      (* Active state enumeration value for SCADA / HMI animation *)
END_VAR

VAR
    (* Internal State Machine Sequencing *)
    iRefiningStep           : INT := 0; (* Internal sequencer state register *)
    tStepTimer              : TON;      (* Step dwell and timeout supervision timer *)
    tPulseTimerA            : TON;      (* Pulse shock clearing duration timer for Plug A *)
    tPulseTimerB            : TON;      (* Pulse shock clearing duration timer for Plug B *)

    (* 2oo3 Triple Modular Redundancy (TMR) Channel Health Registers *)
    bTempSens1_Valid        : BOOL := TRUE;
    bTempSens2_Valid        : BOOL := TRUE;
    bTempSens3_Valid        : BOOL := TRUE;
    bPlugA_Sens1_Valid      : BOOL := TRUE;
    bPlugA_Sens2_Valid      : BOOL := TRUE;
    bPlugA_Sens3_Valid      : BOOL := TRUE;
    bPlugB_Sens1_Valid      : BOOL := TRUE;
    bPlugB_Sens2_Valid      : BOOL := TRUE;
    bPlugB_Sens3_Valid      : BOOL := TRUE;

    (* Porous Plug Degradation and Health Observers *)
    rImpedance_PlugA        : REAL := 0.0; (* Dynamic hydraulic flow resistance Z = P / Q [bar / (Nm3/h)] *)
    rImpedance_PlugB        : REAL := 0.0; (* Dynamic hydraulic flow resistance Z = P / Q [bar / (Nm3/h)] *)
    bPlugA_Clogged          : BOOL := FALSE;
    bPlugB_Clogged          : BOOL := FALSE;
    bPlugA_ErodedBreakout   : BOOL := FALSE;
    bPlugB_ErodedBreakout   : BOOL := FALSE;
    bPlugA_Active           : BOOL := TRUE;
    bPlugB_Active           : BOOL := TRUE;
    bDegradedToSinglePlug   : BOOL := FALSE;
    bDegradedToTopLance     : BOOL := FALSE;

    (* Model Predictive Control (MPC) and State-Space Matrices *)
    (* State Vector: x[0] = [S] (ppm), x[1] = d[S]/dt (ppm/s), x[2] = T_bath (deg C) *)
    rState_x                : ARRAY[0..2] OF REAL := [0.0, 0.0, 1600.0];
    rA_sys                  : ARRAY[0..2, 0..2] OF REAL; (* Discrete system transition matrix *)
    rB_sys                  : ARRAY[0..2] OF REAL;       (* Control input coupling matrix *)
    rC_sys                  : ARRAY[0..2] OF REAL;       (* Measurement output matrix *)
    rMPC_Weight_Q           : REAL := 2.5;               (* Tracking penalty on sulfur error *)
    rMPC_Weight_R           : REAL := 0.15;              (* Actuator movement rate-of-change penalty *)
    rMPC_PredictedS         : ARRAY[1..3] OF REAL;       (* 3-step prediction horizon buffer *)
    rDeltaFlowDemand        : REAL := 0.0;

    (* Thermodynamic Equilibrium and Slag Balance Variables *)
    rOpticalBasicity        : REAL := 0.72; (* Slag optical basicity Lambda *)
    rSulfideCapacity_Cs     : REAL := 0.001;(* Sulfide capacity C_S *)
    rPartitionRatio_Ls      : REAL := 150.0;(* Sulfur distribution partition coefficient L_S *)
    rMassTransferCoeff_kLS  : REAL := 0.0;  (* Volumetric mass transfer coefficient k_LS * (A/V) [1/s] *)
    rBathDepth_m            : REAL := 3.25; (* Liquid steel bath depth in 180-ton ladle [m] *)
    rSteelDensity_kg_m3     : REAL := 7020.0;(* Liquid steel density at 1600 deg C [kg/m3] *)

    (* Numerical Integration and Filtering Accumulators *)
    rCycleTime_sec          : REAL := 0.1;
    rFilteredArgonFlow      : REAL := 0.0;
    rFlowTrackingIntegral   : REAL := 0.0;
    rLastFlowSetpoint       : REAL := 0.0;
    rInitialSulfurSampled   : REAL := 0.0;
    bInitialSulfurCaptured  : BOOL := FALSE;
END_VAR

(*
 * ===================================================================================================
 * CRITICAL SAFETY GATE: HARDWIRED EMERGENCY STOP AND SIL-3 INTERLOCK MONITORING
 * ===================================================================================================
 *)
IF NOT bEmergencyStop THEN
    (* Immediate failsafe de-energization of gas valves and electrical heating interlocks *)
    bSystemReady            := FALSE;
    bSequenceActive         := FALSE;
    rArgonFlowSetpoint_Nm3h := 0.0;
    rPlugA_ControlValve_pct := 0.0;
    rPlugB_ControlValve_pct := 0.0;
    bEmergencyLanceDeploy   := FALSE;
    bPulseBurnoutCmd_A      := FALSE;
    bPulseBurnoutCmd_B      := FALSE;
    iRefiningStep           := 99; (* Transition directly to emergency shutdown state *)
    iOperatingState         := 99;
    wAlarmWord1             := wAlarmWord1 OR 16#0001; (* Latched E-Stop fault *)
    RETURN;
END_IF;

(* Evaluate execution sample period from scan cycle time *)
IF tScanCycleTime > T#0MS THEN
    rCycleTime_sec := TIME_TO_REAL(tScanCycleTime) / 1000.0;
ELSE
    rCycleTime_sec := 0.100; (* Default fallback to 100ms scan cycle *)
END_IF;

(* Clear alarms on operator manual acknowledgement *)
IF bAcknowledgeFaults THEN
    wAlarmWord1 := 16#0000;
    wAlarmWord2 := 16#0000;
END_IF;

(*
 * ===================================================================================================
 * 1. 2oo3 TRIPLE MODULAR REDUNDANCY (TMR) SENSOR VOTING AND FAULT DETECTION
 * ===================================================================================================
 *)
(* --- 1.1 Bath Temperature 2oo3 Median Voting Logic --- *)
(* Channel discrepancy check: maximum allowable divergence between sensors is 35.0 deg C *)
bTempSens1_Valid := (rBathTempSens1_degC >= 1480.0) AND (rBathTempSens1_degC <= 1750.0);
bTempSens2_Valid := (rBathTempSens2_degC >= 1480.0) AND (rBathTempSens2_degC <= 1750.0);
bTempSens3_Valid := (rBathTempSens3_degC >= 1480.0) AND (rBathTempSens3_degC <= 1750.0);

IF bTempSens1_Valid AND bTempSens2_Valid AND bTempSens3_Valid THEN
    (* Full 3-channel availability: Perform Median Selection *)
    IF (rBathTempSens1_degC >= rBathTempSens2_degC AND rBathTempSens1_degC <= rBathTempSens3_degC) OR
       (rBathTempSens1_degC <= rBathTempSens2_degC AND rBathTempSens1_degC >= rBathTempSens3_degC) THEN
        rVotedBathTemp_degC := rBathTempSens1_degC;
    ELSIF (rBathTempSens2_degC >= rBathTempSens1_degC AND rBathTempSens2_degC <= rBathTempSens3_degC) OR
          (rBathTempSens2_degC <= rBathTempSens1_degC AND rBathTempSens2_degC >= rBathTempSens3_degC) THEN
        rVotedBathTemp_degC := rBathTempSens2_degC;
    ELSE
        rVotedBathTemp_degC := rBathTempSens3_degC;
    END_IF;
ELSIF bTempSens1_Valid AND bTempSens2_Valid THEN
    rVotedBathTemp_degC := (rBathTempSens1_degC + rBathTempSens2_degC) * 0.5;
    wAlarmWord2 := wAlarmWord2 OR 16#0001; (* Temperature Channel 3 degradation *)
ELSIF bTempSens1_Valid AND bTempSens3_Valid THEN
    rVotedBathTemp_degC := (rBathTempSens1_degC + rBathTempSens3_degC) * 0.5;
    wAlarmWord2 := wAlarmWord2 OR 16#0002; (* Temperature Channel 2 degradation *)
ELSIF bTempSens2_Valid AND bTempSens3_Valid THEN
    rVotedBathTemp_degC := (rBathTempSens2_degC + rBathTempSens3_degC) * 0.5;
    wAlarmWord2 := wAlarmWord2 OR 16#0004; (* Temperature Channel 1 degradation *)
ELSIF bTempSens1_Valid THEN
    rVotedBathTemp_degC := rBathTempSens1_degC;
    wAlarmWord1 := wAlarmWord1 OR 16#0004; (* Degraded to 1oo3 simplex *)
ELSE
    rVotedBathTemp_degC := 1600.0; (* Safe metallurgical default for high-alloy steel *)
    wAlarmWord1 := wAlarmWord1 OR 16#0008; (* Complete TMR pyrometry failure *)
END_IF;

(* --- 1.2 Porous Plug A Back-Pressure 2oo3 Voting Logic --- *)
bPlugA_Sens1_Valid := (rPlugA_PresSens1_bar >= 0.5) AND (rPlugA_PresSens1_bar <= 25.0);
bPlugA_Sens2_Valid := (rPlugA_PresSens2_bar >= 0.5) AND (rPlugA_PresSens2_bar <= 25.0);
bPlugA_Sens3_Valid := (rPlugA_PresSens3_bar >= 0.5) AND (rPlugA_PresSens3_bar <= 25.0);

IF bPlugA_Sens1_Valid AND bPlugA_Sens2_Valid AND bPlugA_Sens3_Valid THEN
    IF (rPlugA_PresSens1_bar >= rPlugA_PresSens2_bar AND rPlugA_PresSens1_bar <= rPlugA_PresSens3_bar) OR
       (rPlugA_PresSens1_bar <= rPlugA_PresSens2_bar AND rPlugA_PresSens1_bar >= rPlugA_PresSens3_bar) THEN
        rVotedPlugA_Pres_bar := rPlugA_PresSens1_bar;
    ELSIF (rPlugA_PresSens2_bar >= rPlugA_PresSens1_bar AND rPlugA_PresSens2_bar <= rPlugA_PresSens3_bar) OR
          (rPlugA_PresSens2_bar <= rPlugA_PresSens1_bar AND rPlugA_PresSens2_bar >= rPlugA_PresSens3_bar) THEN
        rVotedPlugA_Pres_bar := rPlugA_PresSens2_bar;
    ELSE
        rVotedPlugA_Pres_bar := rPlugA_PresSens3_bar;
    END_IF;
ELSIF bPlugA_Sens1_Valid AND bPlugA_Sens2_Valid THEN
    rVotedPlugA_Pres_bar := (rPlugA_PresSens1_bar + rPlugA_PresSens2_bar) * 0.5;
ELSE
    rVotedPlugA_Pres_bar := rPlugA_PresSens1_bar;
END_IF;

(* --- 1.3 Porous Plug B Back-Pressure 2oo3 Voting Logic --- *)
bPlugB_Sens1_Valid := (rPlugB_PresSens1_bar >= 0.5) AND (rPlugB_PresSens1_bar <= 25.0);
bPlugB_Sens2_Valid := (rPlugB_PresSens2_bar >= 0.5) AND (rPlugB_PresSens2_bar <= 25.0);
bPlugB_Sens3_Valid := (rPlugB_PresSens3_bar >= 0.5) AND (rPlugB_PresSens3_bar <= 25.0);

IF bPlugB_Sens1_Valid AND bPlugB_Sens2_Valid AND bPlugB_Sens3_Valid THEN
    IF (rPlugB_PresSens1_bar >= rPlugB_PresSens2_bar AND rPlugB_PresSens1_bar <= rPlugB_PresSens3_bar) OR
       (rPlugB_PresSens1_bar <= rPlugB_PresSens2_bar AND rPlugB_PresSens1_bar >= rPlugB_PresSens3_bar) THEN
        rVotedPlugB_Pres_bar := rPlugB_PresSens1_bar;
    ELSIF (rPlugB_PresSens2_bar >= rPlugB_PresSens1_bar AND rPlugB_PresSens2_bar <= rPlugB_PresSens3_bar) OR
          (rPlugB_PresSens2_bar <= rPlugB_PresSens1_bar AND rPlugB_PresSens2_bar >= rPlugB_PresSens3_bar) THEN
        rVotedPlugB_Pres_bar := rPlugB_PresSens2_bar;
    ELSE
        rVotedPlugB_Pres_bar := rPlugB_PresSens3_bar;
    END_IF;
ELSIF bPlugB_Sens1_Valid AND bPlugB_Sens2_Valid THEN
    rVotedPlugB_Pres_bar := (rPlugB_PresSens1_bar + rPlugB_PresSens2_bar) * 0.5;
ELSE
    rVotedPlugB_Pres_bar := rPlugB_PresSens1_bar;
END_IF;

(*
 * ===================================================================================================
 * 2. POROUS PLUG HYDRAULIC IMPEDANCE DIAGNOSTICS & DEGRADATION HANDLING
 * ===================================================================================================
 *)
(* Calculate dynamic hydraulic flow impedance Z = P_voted / (Q_actual / 2.0 + epsilon) *)
IF rArgonFlowActual_Nm3h > 1.0 THEN
    rImpedance_PlugA := rVotedPlugA_Pres_bar / (rArgonFlowActual_Nm3h * 0.5);
    rImpedance_PlugB := rVotedPlugB_Pres_bar / (rArgonFlowActual_Nm3h * 0.5);
ELSE
    rImpedance_PlugA := rVotedPlugA_Pres_bar / 0.5;
    rImpedance_PlugB := rVotedPlugB_Pres_bar / 0.5;
END_IF;

(* Threshold diagnostics: Normal impedance band is [0.08 .. 0.45] bar/(Nm3/h) *)
bPlugA_Clogged := (rImpedance_PlugA > 0.55) AND (rVotedPlugA_Pres_bar > 8.0);
bPlugB_Clogged := (rImpedance_PlugB > 0.55) AND (rVotedPlugB_Pres_bar > 8.0);

(* Breakthrough / Severe Refractory Erosion Detection: Extremely low back-pressure at active flow *)
bPlugA_ErodedBreakout := (rImpedance_PlugA < 0.035) AND (rArgonFlowActual_Nm3h > 15.0);
bPlugB_ErodedBreakout := (rImpedance_PlugB < 0.035) AND (rArgonFlowActual_Nm3h > 15.0);

(* Alarm bitmask updates for porous plugs *)
IF bPlugA_Clogged THEN wAlarmWord2 := wAlarmWord2 OR 16#0010; END_IF;
IF bPlugB_Clogged THEN wAlarmWord2 := wAlarmWord2 OR 16#0020; END_IF;
IF bPlugA_ErodedBreakout THEN wAlarmWord1 := wAlarmWord1 OR 16#0010; END_IF;
IF bPlugB_ErodedBreakout THEN wAlarmWord1 := wAlarmWord1 OR 16#0020; END_IF;

(* Automatic Plug Reconfiguration and Graceful Degradation Logic *)
IF bPlugA_ErodedBreakout AND NOT bPlugB_ErodedBreakout THEN
    bPlugA_Active := FALSE;
    bPlugB_Active := TRUE;
    bDegradedToSinglePlug := TRUE;
ELSIF bPlugB_ErodedBreakout AND NOT bPlugA_ErodedBreakout THEN
    bPlugA_Active := TRUE;
    bPlugB_Active := FALSE;
    bDegradedToSinglePlug := TRUE;
ELSIF bPlugA_ErodedBreakout AND bPlugB_ErodedBreakout THEN
    bPlugA_Active := FALSE;
    bPlugB_Active := FALSE;
    bDegradedToTopLance := TRUE;
    wAlarmWord1 := wAlarmWord1 OR 16#0040; (* Total bottom porous plug loss *)
ELSE
    bPlugA_Active := TRUE;
    bPlugB_Active := TRUE;
    bDegradedToSinglePlug := FALSE;
    bDegradedToTopLance := FALSE;
END_IF;

(*
 * ===================================================================================================
 * 3. METALLURGICAL EQUILIBRIUM & KINETIC BALANCE ENGINE
 * ===================================================================================================
 *)
(* Slag Optical Basicity (Duffy & Ingram / Sosinsky & Sommerville correlation) *)
IF rSlagBasicity_B2 > 0.5 THEN
    rOpticalBasicity := 0.59 + 0.065 * (rSlagBasicity_B2 - 1.0) - 0.0018 * rSlagAl2O3_pct;
ELSE
    rOpticalBasicity := 0.65;
END_IF;
IF rOpticalBasicity < 0.55 THEN rOpticalBasicity := 0.55; END_IF;
IF rOpticalBasicity > 0.85 THEN rOpticalBasicity := 0.85; END_IF;

(* Sulfide Capacity log10(C_S) = -13913 / T_bath_kelvin + 42.42 * Lambda - 11.75 *)
rSulfideCapacity_Cs := EXPT(10.0, (-13913.0 / (rVotedBathTemp_degC + 273.15) + 42.42 * rOpticalBasicity - 11.75));
IF rSulfideCapacity_Cs < 0.0001 THEN rSulfideCapacity_Cs := 0.0001; END_IF;

(* Equilibrium Sulfur Partition Ratio L_S = (wt% S)_slag / [wt% S]_steel *)
(* Strongly retarded by dissolved oxygen activity and reducible slag oxides (FeO + MnO) *)
IF (rDissolvedOxygen_ppm > 0.5) AND (rSlagFeO_MnO_pct > 0.1) THEN
    rPartitionRatio_Ls := (rSulfideCapacity_Cs * 10000.0) / (rDissolvedOxygen_ppm * 0.18 + rSlagFeO_MnO_pct * 12.5);
ELSE
    rPartitionRatio_Ls := 80.0;
END_IF;
IF rPartitionRatio_Ls < 10.0 THEN rPartitionRatio_Ls := 10.0; END_IF;
IF rPartitionRatio_Ls > 450.0 THEN rPartitionRatio_Ls := 450.0; END_IF;

(* Theoretical equilibrium sulfur endpoint limit [S]_eq in steel [ppm] *)
IF (rSlagMass_ton > 1.0) AND (rSteelMass_ton > 50.0) THEN
    rEquilibriumSulfur_ppm := (rInitialSulfur_ppm * rSteelMass_ton) / 
                              (rSteelMass_ton + rPartitionRatio_Ls * rSlagMass_ton);
ELSE
    rEquilibriumSulfur_ppm := 12.0;
END_IF;

(* Specific Stirring Energy Dissipation Rate epsilon [W/ton] (Mori & Nomura model) *)
IF (rSteelMass_ton > 10.0) AND (rArgonFlowActual_Nm3h > 0.5) THEN
    rStirringPower_W_ton := (14.23 * rArgonFlowActual_Nm3h / rSteelMass_ton) * 
                            (rVotedBathTemp_degC + 273.15) * 
                            LN(1.0 + (0.00968 * rSteelDensity_kg_m3 * rBathDepth_m / 101325.0));
ELSE
    rStirringPower_W_ton := 0.0;
END_IF;

(* Ladle Open Slag Eye Diameter Model [m] (Asai & Szekely formulation) *)
(* Prevents atmospheric re-oxidation, nitrogen pickup, and radiant refractory damage *)
IF rArgonFlowActual_Nm3h > 1.0 THEN
    rEyeDiameter_m := 0.32 * SQRT((rArgonFlowActual_Nm3h / 3600.0) / SQRT(9.81 * rBathDepth_m)) * 
                      (rVotedBathTemp_degC / 1600.0);
ELSE
    rEyeDiameter_m := 0.0;
END_IF;

IF rEyeDiameter_m > 1.20 THEN
    wAlarmWord2 := wAlarmWord2 OR 16#0040; (* Excessive open eye: re-oxidation / nitrogen pick-up danger *)
END_IF;

(* Volumetric Desulfurization Mass Transfer Coefficient k_LS * (A / V) [1/s] *)
IF rStirringPower_W_ton > 1.0 THEN
    rMassTransferCoeff_kLS := 0.00014 * SQRT(rStirringPower_W_ton) * 
                              (rOpticalBasicity / 0.70) / (1.0 + 0.35 * rSlagFeO_MnO_pct);
ELSE
    rMassTransferCoeff_kLS := 0.00002;
END_IF;

(*
 * ===================================================================================================
 * 4. DISCRETE-TIME STATE-SPACE OBSERVER & MODEL PREDICTIVE CONTROL (MPC)
 * ===================================================================================================
 *)
(* Capture initial metallurgical assay on sequence initiation *)
IF NOT bInitialSulfurCaptured AND (rInitialSulfur_ppm > 0.0) THEN
    rState_x[0] := rInitialSulfur_ppm;
    rInitialSulfurSampled := rInitialSulfur_ppm;
    bInitialSulfurCaptured := TRUE;
END_IF;

(* Dynamic state-space continuous model discretization:
 * dx[0]/dt = -k_LS*(A/V) * (x[0] - [S]_eq)
 * dx[1]/dt = d2[S]/dt2 (rate rate)
 * dx[2]/dt = Cooling / Heating balance = C_arc * I_arc - C_stir * Q_Ar - Q_losses
 *)
rA_sys[0,0] := 1.0 - rMassTransferCoeff_kLS * rCycleTime_sec;
rA_sys[0,1] := rCycleTime_sec;
rA_sys[0,2] := 0.0;

rA_sys[1,0] := 0.0;
rA_sys[1,1] := 0.92; (* Inertial damping on kinetic rate *)
rA_sys[1,2] := 0.0;

rA_sys[2,0] := 0.0;
rA_sys[2,1] := 0.0;
rA_sys[2,2] := 1.0 - 0.00015 * rCycleTime_sec; (* Radiation loss thermal decay *)

(* Control Input coupling matrix B_sys *)
rB_sys[0] := -0.00045 * rCycleTime_sec; (* Sensitivity of sulfur removal to argon flow *)
rB_sys[1] := -0.00012 * rCycleTime_sec;
rB_sys[2] := -0.03800 * rCycleTime_sec; (* Argon bubble thermal quenching effect [deg C / (Nm3/h)] *)

(* Execute Observer State Step Integration *)
rState_x[0] := rA_sys[0,0] * rState_x[0] + rA_sys[0,1] * rState_x[1] + 
               rB_sys[0] * rArgonFlowActual_Nm3h + 
               rMassTransferCoeff_kLS * rCycleTime_sec * rEquilibriumSulfur_ppm;

(* Boundary clamping on physical dissolved sulfur concentration *)
IF rState_x[0] < rEquilibriumSulfur_ppm THEN
    rState_x[0] := rEquilibriumSulfur_ppm;
END_IF;

rEstimatedSulfur_ppm := rState_x[0];

(* Instantaneous Desulfurization Rate [ppm/min] *)
rDesulfRate_ppm_per_min := rMassTransferCoeff_kLS * (rState_x[0] - rEquilibriumSulfur_ppm) * 60.0;

(* Model Predictive Control (MPC) Horizon Analytical Solver *)
(* Evaluates 3-step forward predictions to minimize tracking error [S] - [S]_target *)
IF bAutoMode AND (iRefiningStep = 40) THEN
    (* Step 1 Horizon Prediction *)
    rMPC_PredictedS[1] := rState_x[0] - rMassTransferCoeff_kLS * (rState_x[0] - rEquilibriumSulfur_ppm) * 5.0;
    (* Step 2 Horizon Prediction *)
    rMPC_PredictedS[2] := rMPC_PredictedS[1] - rMassTransferCoeff_kLS * (rMPC_PredictedS[1] - rEquilibriumSulfur_ppm) * 5.0;
    (* Step 3 Horizon Prediction *)
    rMPC_PredictedS[3] := rMPC_PredictedS[2] - rMassTransferCoeff_kLS * (rMPC_PredictedS[2] - rEquilibriumSulfur_ppm) * 5.0;

    (* Analytical Gradient Descent on Quadratic Cost J = sum(w_Q*(S_pred - S_target)^2) + w_R*(delta_u)^2 *)
    rDeltaFlowDemand := (rMPC_Weight_Q * (rMPC_PredictedS[3] - rTargetSulfur_ppm) * 0.85) / 
                        (rMPC_Weight_Q * 0.75 + rMPC_Weight_R);

    (* Constrain MPC flow rate adjustments to prevent open eye blowout and ladle metal splashing *)
    IF rDeltaFlowDemand > 12.0 THEN rDeltaFlowDemand := 12.0; END_IF;
    IF rDeltaFlowDemand < -15.0 THEN rDeltaFlowDemand := -15.0; END_IF;

    rArgonFlowSetpoint_Nm3h := rArgonFlowSetpoint_Nm3h + rDeltaFlowDemand * rCycleTime_sec * 0.2;
END_IF;

(* Target check with 2.0 ppm metallurgical engineering deadband *)
bDesulfTargetReached := (rEstimatedSulfur_ppm <= (rTargetSulfur_ppm + 1.5)) AND bInitialSulfurCaptured;

(*
 * ===================================================================================================
 * 5. MULTI-STAGE REFINING FINITE STATE MACHINE (CASE)
 * ===================================================================================================
 *)
CASE iRefiningStep OF
    0: (* STATE_INIT_STANDBY_VERIFICATION *)
        bSystemReady            := FALSE;
        bSequenceActive         := FALSE;
        rArgonFlowSetpoint_Nm3h := 0.0;
        rPlugA_ControlValve_pct := 0.0;
        rPlugB_ControlValve_pct := 0.0;
        bEmergencyLanceDeploy   := FALSE;
        bPulseBurnoutCmd_A      := FALSE;
        bPulseBurnoutCmd_B      := FALSE;
        bInitialSulfurCaptured  := FALSE;
        wStatusWord             := 16#0000;

        IF bEnable AND (rArgonSupplyPress_bar >= 8.5) THEN
            bSystemReady := TRUE;
            wStatusWord  := 16#0001; (* Standby Ready *)
            IF bAutoMode THEN
                iRefiningStep := 10; (* Proceed to Standby Seated Purge *)
            END_IF;
        END_IF;

    10: (* STATE_STANDBY_SEATED_PURGE: Gentle positive gas flow to prevent molten steel infiltration *)
        bSequenceActive := TRUE;
        wStatusWord     := 16#0002; (* Purge Active *)
        rArgonFlowSetpoint_Nm3h := 8.0; (* Base anti-clogging positive purge [Nm3/h] *)

        (* Execute pulse clearing shock if porous plugs exhibit high startup impedance *)
        IF bPlugA_Clogged THEN
            bPulseBurnoutCmd_A := TRUE;
            tPulseTimerA(IN := TRUE, PT := T#4S);
            IF tPulseTimerA.Q THEN
                bPulseBurnoutCmd_A := FALSE;
                tPulseTimerA(IN := FALSE);
            END_IF;
        ELSE
            bPulseBurnoutCmd_A := FALSE;
            tPulseTimerA(IN := FALSE);
        END_IF;

        IF bPlugB_Clogged THEN
            bPulseBurnoutCmd_B := TRUE;
            tPulseTimerB(IN := TRUE, PT := T#4S);
            IF tPulseTimerB.Q THEN
                bPulseBurnoutCmd_B := FALSE;
                tPulseTimerB(IN := FALSE);
            END_IF;
        ELSE
            bPulseBurnoutCmd_B := FALSE;
            tPulseTimerB(IN := FALSE);
        END_IF;

        (* Advance when ladle is fully seated and electrodes ready to strike *)
        tStepTimer(IN := TRUE, PT := T#30S);
        IF tStepTimer.Q THEN
            tStepTimer(IN := FALSE);
            iRefiningStep := 20; (* Proceed to Arc Heating & Deoxidation *)
        END_IF;

    20: (* STATE_ARC_HEATING_DEOXIDATION: Moderate stirring for temperature homogenization and arc stability *)
        wStatusWord := 16#0004; (* Arc Heating Active *)
        rArgonFlowSetpoint_Nm3h := 22.0; (* Stable bubbling flow [Nm3/h] *)

        (* Arc heating safety interlock: if argon flow is completely lost, throttle back arc power *)
        IF rArgonFlowActual_Nm3h < 3.0 THEN
            wAlarmWord1 := wAlarmWord1 OR 16#0080; (* Arc Heating with zero bottom stirring hazard *)
        END_IF;

        (* Check deoxidation progress: celox dissolved oxygen must drop below 8 ppm *)
        IF (rDissolvedOxygen_ppm <= 6.0) AND (rVotedBathTemp_degC >= 1585.0) THEN
            iRefiningStep := 30; (* Proceed to Synthetic Slag Fluxing *)
        END_IF;

    30: (* STATE_SYNTHETIC_SLAG_FLUXING: Lime/Fluorspar dissolution, slag deoxidation & basicity conditioning *)
        wStatusWord := 16#0008; (* Slag Conditioning *)
        rArgonFlowSetpoint_Nm3h := 45.0; (* Intermediate emulsification flow rate [Nm3/h] *)

        (* Slag basicity and oxidation criteria for effective sulfur capture: *)
        (* Binary basicity B2 > 2.8 and (FeO + MnO) < 0.8 wt% *)
        IF (rSlagBasicity_B2 >= 2.6) AND (rSlagFeO_MnO_pct <= 0.85) AND (rVotedBathTemp_degC >= 1605.0) THEN
            iRefiningStep := 40; (* Proceed to High-Intensity MPC Desulfurization *)
        END_IF;

    40: (* STATE_DEEP_DESULFURIZATION_MPC: Intensive stirring for high interfacial slag-metal contact area *)
        wStatusWord := 16#0010; (* Deep Desulfurization Running *)

        (* Ensure minimum baseline flow of 55 Nm3/h for slag emulsification if MPC drops too low *)
        IF rArgonFlowSetpoint_Nm3h < 55.0 THEN
            rArgonFlowSetpoint_Nm3h := 55.0;
        END_IF;
        (* Upper ceiling constraint: prevent open eye from exceeding 1.10m and avoid ladle breakout *)
        IF (rArgonFlowSetpoint_Nm3h > 115.0) OR (rEyeDiameter_m > 1.05) THEN
            rArgonFlowSetpoint_Nm3h := 105.0;
        END_IF;

        (* Fallback to degraded modes if porous plug failure occurs *)
        IF bDegradedToTopLance THEN
            iRefiningStep := 90; (* Divert to Top Lance Fallback *)
        ELSIF bDesulfTargetReached THEN
            tStepTimer(IN := TRUE, PT := T#45S); (* Dwell verification *)
            IF tStepTimer.Q THEN
                tStepTimer(IN := FALSE);
                iRefiningStep := 50; (* Proceed to Inclusion Flotation Rinsing *)
            END_IF;
        ELSE
            tStepTimer(IN := FALSE);
        END_IF;

    50: (* STATE_INCLUSION_FLOTATION_RINSING: Gentle soft stirring for alumina / spinel cluster flotation *)
        wStatusWord := 16#0020; (* Soft Rinsing Active *)
        rArgonFlowSetpoint_Nm3h := 12.0; (* Dead-soft bubbling, completely closed slag eye [Nm3/h] *)

        (* Verify eye is completely closed to avoid secondary air re-oxidation *)
        IF rEyeDiameter_m > 0.35 THEN
            rArgonFlowSetpoint_Nm3h := 8.5;
        END_IF;

        tStepTimer(IN := TRUE, PT := T#180S); (* 3-minute metallurgical clean steel rinsing window *)
        IF tStepTimer.Q THEN
            tStepTimer(IN := FALSE);
            iRefiningStep := 60; (* Proceed to Calcium Wire Treatment *)
        END_IF;

    60: (* STATE_CALCIUM_TREATMENT_HOLD: CaSi wire injection for inclusion shape morphology modification *)
        wStatusWord := 16#0040; (* Calcium Treatment Active *)
        rArgonFlowSetpoint_Nm3h := 9.0; (* Gentle stirring to maximize Ca recovery in molten steel *)

        tStepTimer(IN := TRUE, PT := T#90S);
        IF tStepTimer.Q THEN
            tStepTimer(IN := FALSE);
            iRefiningStep := 70; (* Treatment Complete *)
        END_IF;

    70: (* STATE_TREATMENT_COMPLETE: Steel grade ready for continuous casting machine *)
        wStatusWord := 16#0080; (* Heat Completed *)
        rArgonFlowSetpoint_Nm3h := 6.0; (* Low idle bubbling to maintain thermal stratification control *)
        bSequenceActive := FALSE;

        IF NOT bEnable THEN
            iRefiningStep := 0; (* Reset sequencer *)
        END_IF;

    90: (* STATE_DEGRADED_TOP_LANCE_FALLBACK: Emergency mode upon complete bottom porous plug loss *)
        wStatusWord := 16#0100; (* Degraded Top Lance Operation *)
        wAlarmWord2 := wAlarmWord2 OR 16#0100;
        bEmergencyLanceDeploy := TRUE;
        rArgonFlowSetpoint_Nm3h := 65.0; (* Top lance injection demand [Nm3/h] *)

        (* Close bottom valve lines to isolate damaged ladle refractory plugs *)
        rPlugA_ControlValve_pct := 0.0;
        rPlugB_ControlValve_pct := 0.0;

        IF bDesulfTargetReached THEN
            iRefiningStep := 50; (* Transition to soft rinse via top lance *)
        END_IF;

    99: (* STATE_EMERGENCY_FAILSAFE_SHUTDOWN: Safe hardware isolation on critical safety abort *)
        wStatusWord             := 16#8000; (* Safety Trip State *)
        rArgonFlowSetpoint_Nm3h := 0.0;
        rPlugA_ControlValve_pct := 0.0;
        rPlugB_ControlValve_pct := 0.0;
        bEmergencyLanceDeploy   := FALSE;
        bPulseBurnoutCmd_A      := FALSE;
        bPulseBurnoutCmd_B      := FALSE;
        bSequenceActive         := FALSE;
        bSystemReady            := FALSE;

        IF bEnable AND bEmergencyStop AND bAcknowledgeFaults THEN
            iRefiningStep := 0; (* Clear shutdown state upon operator authorized reset *)
        END_IF;

    ELSE
        iRefiningStep := 99; (* Unhandled condition failsafe vector *)
END_CASE;

(* Update export state indicator *)
iOperatingState := iRefiningStep;

(*
 * ===================================================================================================
 * 6. VALVE ACTUATOR SPLIT-RANGE POSITIONING & FLOW TRACKING SERVO
 * ===================================================================================================
 *)
(* Closed-loop integral trim on mass flow controller delivery *)
rFlowTrackingIntegral := rFlowTrackingIntegral + (rArgonFlowSetpoint_Nm3h - rArgonFlowActual_Nm3h) * (rCycleTime_sec * 0.4);
IF rFlowTrackingIntegral > 20.0 THEN rFlowTrackingIntegral := 20.0; END_IF;
IF rFlowTrackingIntegral < -20.0 THEN rFlowTrackingIntegral := -20.0; END_IF;

(* Porous Plug Actuation Split-Range Allocation *)
IF NOT bDegradedToTopLance AND (iRefiningStep <> 99) THEN
    IF bPlugA_Active AND bPlugB_Active THEN
        (* Balanced dual-plug symmetrical injection *)
        rPlugA_ControlValve_pct := (rArgonFlowSetpoint_Nm3h * 0.5 * 1.8) + rFlowTrackingIntegral * 0.5;
        rPlugB_ControlValve_pct := (rArgonFlowSetpoint_Nm3h * 0.5 * 1.8) + rFlowTrackingIntegral * 0.5;
    ELSIF bPlugA_Active AND NOT bPlugB_Active THEN
        (* Asymmetric single plug operation on Plug A *)
        rPlugA_ControlValve_pct := (rArgonFlowSetpoint_Nm3h * 1.85) + rFlowTrackingIntegral;
        rPlugB_ControlValve_pct := 0.0;
    ELSIF NOT bPlugA_Active AND bPlugB_Active THEN
        (* Asymmetric single plug operation on Plug B *)
        rPlugA_ControlValve_pct := 0.0;
        rPlugB_ControlValve_pct := (rArgonFlowSetpoint_Nm3h * 1.85) + rFlowTrackingIntegral;
    ELSE
        rPlugA_ControlValve_pct := 0.0;
        rPlugB_ControlValve_pct := 0.0;
    END_IF;
ELSE
    (* Bottom plugs isolated in top lance fallback or failsafe mode *)
    rPlugA_ControlValve_pct := 0.0;
    rPlugB_ControlValve_pct := 0.0;
END_IF;

(* Actuator position saturation clamping [0.0% .. 100.0%] *)
IF rPlugA_ControlValve_pct > 100.0 THEN rPlugA_ControlValve_pct := 100.0; END_IF;
IF rPlugA_ControlValve_pct < 0.0 THEN rPlugA_ControlValve_pct := 0.0; END_IF;
IF rPlugB_ControlValve_pct > 100.0 THEN rPlugB_ControlValve_pct := 100.0; END_IF;
IF rPlugB_ControlValve_pct < 0.0 THEN rPlugB_ControlValve_pct := 0.0; END_IF;

END_FUNCTION_BLOCK
